template: `
    <cs-page-template>
      @if (routeMagnitude()) {
        <cs-breadcrumb breadcrumb [items]="breadcrumb()" />
      }
      <cs-page-header header titleId="bo-units-title" [title]="heading()" [description]="description()">
        @if (canWrite() && magnitudes()) {
          @if (!routeMagnitude()) {
            <cs-button variant="primary" size="sm" (click)="list()?.openRegister()"
              ><cs-icon name="plus" [size]="16" aria-hidden="true" />Registrar magnitud</cs-button
            >
          } @else if (current()?.status === 'ACTIVE') {
            <cs-button variant="primary" size="sm" (click)="list()?.openRegister()"
              ><cs-icon name="plus" [size]="16" aria-hidden="true" />Registrar unidad</cs-button
            >
          }
        }
      </cs-page-header>

      @if (loadError()) {
        <cs-empty-state class="bo-units__state" illustration="load-error" title="No pudimos cargar las unidades." description="Inténtalo de nuevo.">
          <cs-button variant="default" size="sm" (click)="load()">Reintentar</cs-button>
        </cs-empty-state>
      } @else if (!magnitudes()) {
        <div aria-busy="true" aria-label="Cargando unidades"><cs-skeleton width="100%" height="var(--layout-size-2xl)" /></div>
      } @else if (!routeMagnitude()) {
        <bo-catalog-list [config]="magnitudesConfig" [canWrite]="canWrite()" />
      } @else if (current(); as magnitude) {
        @if (baseOf(magnitude); as base) {
          <p class="bo-units__base">
            Unidad base: <strong>{{ base.name }} ({{ base.symbol }})</strong>. Las demás unidades se convierten desde ella.
            @if (magnitude.status === 'INACTIVE') {
              La magnitud está inactiva: los Distribuidores no la ven y no se registran unidades nuevas.
            }
          </p>
        }
        <bo-catalog-list [config]="configFor(magnitude.code)" [canWrite]="canWrite()" />
      } @else {
        <cs-empty-state class="bo-units__state" icon="ruler" title="No encontramos esa magnitud." description="Puede que el enlace esté mal escrito.">
          <cs-button variant="default" size="sm" (click)="backToList()">Ver las magnitudes</cs-button>
        </cs-empty-state>
      }
    </cs-page-template>
  `,
